-- Customer (1) --< Orders (N) >--< M:N OrderItems -- Products

-- Entities become tables
CREATE TABLE customers (id INT PK, name, email);
CREATE TABLE orders (id INT PK, customer_id INT FK, order_date);
CREATE TABLE products (id INT PK, name, price);

-- M:N junction table
CREATE TABLE order_items (
  order_id INT FK, product_id INT FK, quantity INT,
  PRIMARY KEY (order_id, product_id)
);
